/**
 * Procedural papercut layers. Every layer is one SVG path generated from a seeded random
 * generator, so the forest is the same on every load and can be regenerated by changing seeds.
 * Fills reference season custom properties (--s-sky, --s-far, ...) so colours follow the
 * OKLCH season interpolation in seasons.ts.
 */
const W = 1600;
const NS = 'http://www.w3.org/2000/svg';

export function mulberry32(seed: number) {
  return () => {
    seed |= 0; seed = (seed + 0x6d2b79f5) | 0;
    let t = Math.imul(seed ^ (seed >>> 15), 1 | seed);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

/** A smooth ridge line: sum of three sines with random phases, sampled every `step` px. */
function ridge(r: () => number, baseY: number, amp: number, step = 40) {
  const p = [r() * 6.28, r() * 6.28, r() * 6.28];
  const f = [1.2 + r(), 2.6 + r() * 2, 6 + r() * 4];
  const pts: [number, number][] = [];
  for (let x = -step; x <= W + step; x += step) {
    const u = x / W;
    const y = baseY - amp * (0.55 * Math.sin(u * f[0] * Math.PI + p[0]) + 0.3 * Math.sin(u * f[1] * Math.PI + p[1]) + 0.15 * Math.sin(u * f[2] * Math.PI + p[2]));
    pts.push([x, y]);
  }
  return pts;
}

/** Catmull-Rom through points, as cubic Béziers, for soft hand-cut curves. */
function smooth(pts: [number, number][]) {
  let d = `M${pts[0][0].toFixed(1)} ${pts[0][1].toFixed(1)}`;
  for (let i = 0; i < pts.length - 1; i++) {
    const p0 = pts[i - 1] ?? pts[i], p1 = pts[i], p2 = pts[i + 1], p3 = pts[i + 2] ?? p2;
    const c1 = [p1[0] + (p2[0] - p0[0]) / 6, p1[1] + (p2[1] - p0[1]) / 6];
    const c2 = [p2[0] - (p3[0] - p1[0]) / 6, p2[1] - (p3[1] - p1[1]) / 6];
    d += `C${c1[0].toFixed(1)} ${c1[1].toFixed(1)} ${c2[0].toFixed(1)} ${c2[1].toFixed(1)} ${p2[0].toFixed(1)} ${p2[1].toFixed(1)}`;
  }
  return d;
}

function hills(r: () => number, H: number, base: number, amp: number) {
  return `${smooth(ridge(r, base * H, amp * H))}L${W + 60} ${H + 10}L-60 ${H + 10}Z`;
}

/** Ground ridge plus a row of three-tier pines standing on it. */
function pines(r: () => number, H: number, base: number, amp: number, minH: number, maxH: number, gap: number) {
  const line = ridge(r, base * H, amp * H, 20);
  let d = `${smooth(line)}L${W + 60} ${H + 10}L-60 ${H + 10}Z`;
  const yAt = (x: number) => {
    const i = Math.max(0, Math.min(line.length - 2, Math.floor((x + 20) / 20)));
    const t = (x - line[i][0]) / 20;
    return line[i][1] * (1 - t) + line[i + 1][1] * t;
  };
  for (let x = -20 + r() * gap; x < W + 20; x += gap * (0.55 + r() * 0.9)) {
    const h = (minH + r() * (maxH - minH)) * H;
    const w = h * (0.34 + r() * 0.1);
    const y = yAt(x) + 4;
    // three overlapping tiers, each a triangle with a slightly drooping hem
    for (let k = 0; k < 3; k++) {
      const top = y - h + k * h * 0.26;
      const bot = y - h * 0.32 + k * h * 0.3;
      const hw = (w / 2) * (0.62 + k * 0.22);
      d += `M${(x).toFixed(1)} ${top.toFixed(1)}L${(x + hw).toFixed(1)} ${bot.toFixed(1)}Q${x.toFixed(1)} ${(bot - h * 0.05).toFixed(1)} ${(x - hw).toFixed(1)} ${bot.toFixed(1)}Z`;
    }
    d += `M${(x - w * 0.05).toFixed(1)} ${(y - h * 0.1).toFixed(1)}h${(w * 0.1).toFixed(1)}v${(h * 0.14).toFixed(1)}h${(-w * 0.1).toFixed(1)}Z`;
  }
  return d;
}

/** A river that winds from the bottom edge to the horizon, narrowing with distance. */
function river(r: () => number, H: number, horizon: number) {
  const left: [number, number][] = [], right: [number, number][] = [];
  const n = 9;
  for (let i = 0; i <= n; i++) {
    const t = i / n;
    const y = H + 10 - t * (H + 10 - horizon * H);
    const cx = W * (0.5 + 0.22 * Math.sin(t * 5.5 + r() * 0.4) * (1 - t * 0.6));
    const hw = W * (0.2 * (1 - t) ** 1.6 + 0.008);
    left.push([cx - hw, y]);
    right.push([cx + hw, y]);
  }
  return `${smooth(left)}L${right[n][0].toFixed(1)} ${right[n][1].toFixed(1)}${smooth(right.reverse()).replace(/^M/, 'L')}Z`;
}

/** Foreground fern fronds rising from the bottom edge. */
function ferns(r: () => number, H: number, count: number, scale: number) {
  let d = '';
  for (let i = 0; i < count; i++) {
    const bx = (i + 0.2 + r() * 0.6) * (W / count);
    const len = H * scale * (0.7 + r() * 0.5);
    const lean = (r() - 0.5) * 1.1;
    const pts: [number, number][] = [];
    for (let s = 0; s <= 10; s++) {
      const t = s / 10;
      pts.push([bx + Math.sin(t * 1.4) * lean * len * 0.6, H + 6 - t * len]);
    }
    // spine
    d += `M${pts[0][0] - 5} ${pts[0][1]}`;
    for (const p of pts) d += `L${(p[0] - 3).toFixed(1)} ${p[1].toFixed(1)}`;
    for (const p of [...pts].reverse()) d += `L${(p[0] + 3).toFixed(1)} ${p[1].toFixed(1)}`;
    d += 'Z';
    // leaflets, alternating sides, shrinking toward the tip
    for (let s = 1; s < 10; s++) {
      const t = s / 10;
      const [x, y] = pts[s];
      const lw = len * 0.26 * (1 - t) + 6;
      for (const side of [-1, 1]) {
        const tipx = x + side * lw, tipy = y - lw * 0.45;
        d += `M${x.toFixed(1)} ${y.toFixed(1)}Q${(x + side * lw * 0.55).toFixed(1)} ${(y + lw * 0.18).toFixed(1)} ${tipx.toFixed(1)} ${tipy.toFixed(1)}Q${(x + side * lw * 0.4).toFixed(1)} ${(y - lw * 0.32).toFixed(1)} ${x.toFixed(1)} ${(y - 8).toFixed(1)}Z`;
      }
    }
  }
  return d;
}

export type LayerKind = 'sky' | 'hills' | 'pines' | 'river' | 'ferns';
export interface Layer { kind: LayerKind; fill: string; seed: number; base?: number; amp?: number; minH?: number; maxH?: number; gap?: number; count?: number; scale?: number; depth: number }

export function buildLayer(l: Layer, H: number): SVGSVGElement {
  const svg = document.createElementNS(NS, 'svg');
  svg.setAttribute('viewBox', `0 0 ${W} ${H}`);
  svg.setAttribute('preserveAspectRatio', 'xMidYMax slice');
  svg.setAttribute('aria-hidden', 'true');
  svg.setAttribute('class', `layer layer--${l.kind}`);
  svg.style.setProperty('--depth', String(l.depth));
  const r = mulberry32(l.seed);
  if (l.kind === 'sky') {
    const rect = document.createElementNS(NS, 'rect');
    rect.setAttribute('width', String(W)); rect.setAttribute('height', String(H));
    rect.setAttribute('class', 'sky');
    const sun = document.createElementNS(NS, 'circle');
    sun.setAttribute('cx', String(W * 0.72)); sun.setAttribute('cy', String(H * 0.3)); sun.setAttribute('r', String(H * 0.09));
    sun.setAttribute('class', 'sun');
    svg.append(rect, sun);
    return svg;
  }
  const path = document.createElementNS(NS, 'path');
  const d =
    l.kind === 'hills' ? hills(r, H, l.base!, l.amp!)
    : l.kind === 'pines' ? pines(r, H, l.base!, l.amp!, l.minH!, l.maxH!, l.gap!)
    : l.kind === 'river' ? river(r, H, l.base!)
    : ferns(r, H, l.count!, l.scale!);
  path.setAttribute('d', d);
  path.style.fill = l.fill;
  svg.appendChild(path);
  return svg;
}

/** The eight-layer hero valley, back to front. */
export const HERO_LAYERS: Layer[] = [
  { kind: 'sky', fill: '', seed: 1, depth: 0 },
  { kind: 'hills', fill: 'var(--s-far)', seed: 11, base: 0.5, amp: 0.1, depth: 0.1 },
  { kind: 'hills', fill: 'var(--s-mid)', seed: 23, base: 0.6, amp: 0.08, depth: 0.22 },
  { kind: 'pines', fill: 'var(--s-back)', seed: 37, base: 0.66, amp: 0.05, minH: 0.08, maxH: 0.13, gap: 46, depth: 0.36 },
  { kind: 'river', fill: 'var(--s-water)', seed: 41, base: 0.66, depth: 0.45 },
  { kind: 'pines', fill: 'color-mix(in oklch, var(--s-back), var(--s-front))', seed: 53, base: 0.78, amp: 0.05, minH: 0.14, maxH: 0.22, gap: 120, depth: 0.6 },
  { kind: 'pines', fill: 'var(--s-front)', seed: 67, base: 0.95, amp: 0.04, minH: 0.32, maxH: 0.5, gap: 330, depth: 0.82 },
  { kind: 'ferns', fill: 'var(--s-leaf)', seed: 79, count: 7, scale: 0.26, depth: 1 },
];

/** Five-layer card diorama for each tour. */
export const cardLayers = (seed: number): Layer[] => [
  { kind: 'sky', fill: '', seed, depth: 0 },
  { kind: 'hills', fill: 'var(--s-far)', seed: seed + 1, base: 0.52, amp: 0.12, depth: 0.2 },
  { kind: 'pines', fill: 'var(--s-back)', seed: seed + 2, base: 0.68, amp: 0.06, minH: 0.12, maxH: 0.2, gap: 70, depth: 0.45 },
  { kind: 'pines', fill: 'var(--s-front)', seed: seed + 3, base: 0.92, amp: 0.05, minH: 0.3, maxH: 0.46, gap: 260, depth: 0.75 },
  { kind: 'ferns', fill: 'var(--s-leaf)', seed: seed + 4, count: 5, scale: 0.3, depth: 1 },
];

export function mountScene(host: HTMLElement, layers: Layer[], H: number) {
  host.replaceChildren(...layers.map((l, i) => {
    const svg = buildLayer(l, H);
    svg.style.setProperty('--i', String(i));
    return svg;
  }));
}
